// ProjectServiceHandler is an implementation of the toshi.workspace.v1.ProjectService service.
type ProjectServiceHandler interface {
	// ListProjects returns the workspace's projects by name, each with its
	// environments by name.
	//
	// A page holds 100 projects when page_size is zero, and 1000 at most.
	ListProjects(context.Context, *connect.Request[workspacev1.ListProjectsRequest]) (*connect.Response[workspacev1.ListProjectsResponse], error)
	// GetProject returns one project with its environments by name. A
	// project the workspace does not have is NOT_FOUND. A token limited to
	// a project gets only that project, and PERMISSION_DENIED for any other
	// name; a token limited to an environment gets the project with that
	// environment only.
	GetProject(context.Context, *connect.Request[workspacev1.GetProjectRequest]) (*connect.Response[workspacev1.GetProjectResponse], error)
	// ListRepositories returns the repositories the workspace's projects
	// claim, by repository. A project the workspace does not have is
	// NOT_FOUND.
	//
	// A page holds 100 repositories when page_size is zero, and 1000 at most.
	ListRepositories(context.Context, *connect.Request[workspacev1.ListRepositoriesRequest]) (*connect.Response[workspacev1.ListRepositoriesResponse], error)
	// CreateProject makes a project with its three environments,
	// development, preview and production. A name the workspace's projects
	// already have is ALREADY_EXISTS. A token limited to a project is
	// PERMISSION_DENIED: the new project is not its own.
	CreateProject(context.Context, *connect.Request[workspacev1.CreateProjectRequest]) (*connect.Response[workspacev1.CreateProjectResponse], error)
	// UpdateProject sets the fields of project.name's project that
	// update_mask names. The one field it sets is admission, the project's
	// admission webhook: its url and secret, both required, or an empty url
	// to remove it. An unset update_mask names the fields project carries.
	// An empty one, an unset one with no admission, "*" and a path of
	// another field are INVALID_ARGUMENT. The secret is sealed under the
	// workspace's data key and never returned; a deployment with no keyring
	// refuses it with FAILED_PRECONDITION. A token limited to environments
	// is PERMISSION_DENIED.
	UpdateProject(context.Context, *connect.Request[workspacev1.UpdateProjectRequest]) (*connect.Response[workspacev1.UpdateProjectResponse], error)
	// ClaimRepository puts a repository in a project: it claims a repository
	// no project claims, or moves the claim from another project. A CI job
	// whose repository's claim was read before the move keeps its project,
	// and its credentials are refused; a job whose claim is read after it
	// lands in the new project. A project the workspace does not have is NOT_FOUND. A token
	// limited to a project claims only for that project, and only a
	// repository no other project claims.
	ClaimRepository(context.Context, *connect.Request[workspacev1.ClaimRepositoryRequest]) (*connect.Response[workspacev1.ClaimRepositoryResponse], error)
	// CreateEnvironment adds the environment of a kind a project lacks,
	// named after its kind, such as preview for a project made with
	// production only. A kind the project has is ALREADY_EXISTS; a project
	// the workspace does not have is NOT_FOUND. A token limited to a project
	// creates only in that project, and a token limited to an environment
	// is PERMISSION_DENIED.
	CreateEnvironment(context.Context, *connect.Request[workspacev1.CreateEnvironmentRequest]) (*connect.Response[workspacev1.CreateEnvironmentResponse], error)
	// DeleteEnvironment deletes a project's environment by name. A project's
	// production environment is FAILED_PRECONDITION, and so is an
	// environment that anything live still refers to, with each kind and
	// its count in the message: secret sets, API tokens that are neither
	// revoked nor expired, unfinished jobs, workloads that are not deleted,
	// artifacts still being uploaded, the project's branch rules that choose
	// it and its triggers that are not deleted. Finished jobs and complete
	// artifacts keep the environment as history. A project or environment
	// the workspace does not have is NOT_FOUND. A token limited to a
	// project deletes only in that project, and a token limited to an
	// environment is PERMISSION_DENIED.
	DeleteEnvironment(context.Context, *connect.Request[workspacev1.DeleteEnvironmentRequest]) (*connect.Response[workspacev1.DeleteEnvironmentResponse], error)
	// ListBranchRules returns a project's branch rules in order, the
	// fallback rule last: the first that matches a CI job's run chooses the
	// job's environment. The fallback rule takes every other run and never
	// chooses an environment of kind production. A project the workspace does
	// not have is NOT_FOUND. A token limited to a project reads only that
	// project's rules, and a token limited to an environment is
	// PERMISSION_DENIED.
	//
	// A page holds 100 rules when page_size is zero, and 1000 at most.
	ListBranchRules(context.Context, *connect.Request[workspacev1.ListBranchRulesRequest]) (*connect.Response[workspacev1.ListBranchRulesResponse], error)
	// SetBranchRules replaces a project's branch rules with the list given,
	// whole: it has at most 100 rules, a known match on each, a pattern on
	// exactly the pattern rules, no two rules matching the same way, the
	// fallback rule exactly once and last, each environment one of the
	// project's or none, and the fallback rule's environment not a
	// production one. Any other list is INVALID_ARGUMENT and changes
	// nothing. A job already assigned keeps the environment it got; the new
	// rules choose from its next assignment. A project the workspace does
	// not have is NOT_FOUND. A token limited to a project sets only that
	// project's rules, and a token limited to an environment is
	// PERMISSION_DENIED.
	SetBranchRules(context.Context, *connect.Request[workspacev1.SetBranchRulesRequest]) (*connect.Response[workspacev1.SetBranchRulesResponse], error)
	// GetProjectNetwork returns a project's network policy: where its
	// workloads may connect outbound. A project that never set one allows
	// every destination. A project the workspace does not have is NOT_FOUND.
	// A token limited to a project reads only that project's policy, and a
	// token limited to an environment is PERMISSION_DENIED.
	GetProjectNetwork(context.Context, *connect.Request[workspacev1.GetProjectNetworkRequest]) (*connect.Response[workspacev1.GetProjectNetworkResponse], error)
	// SetProjectNetwork replaces a project's network policy whole: the
	// default and the ordered rules. It has at most 100 rules, each an allow
	// or a deny of an address, a CIDR prefix or a DNS name, with an optional
	// port or port range and protocol. Any other policy is INVALID_ARGUMENT
	// and changes nothing. A workload keeps the policy it was admitted with;
	// the new one applies to workloads admitted after it. A project the
	// workspace does not have is NOT_FOUND. A token limited to a project
	// sets only that project's policy, and a token limited to an environment
	// is PERMISSION_DENIED.
	SetProjectNetwork(context.Context, *connect.Request[workspacev1.SetProjectNetworkRequest]) (*connect.Response[workspacev1.SetProjectNetworkResponse], error)
	// GetEnvironmentNetwork returns an environment's network policy, which
	// narrows its project's: a destination is reached only when both allow
	// it. An environment that never set one allows every destination its
	// project allows. A project or environment the workspace does not have is
	// NOT_FOUND. A token limited to an environment reads only that
	// environment's policy.
	GetEnvironmentNetwork(context.Context, *connect.Request[workspacev1.GetEnvironmentNetworkRequest]) (*connect.Response[workspacev1.GetEnvironmentNetworkResponse], error)
	// SetEnvironmentNetwork replaces an environment's network policy whole,
	// checked as SetProjectNetwork checks a project's. It can only narrow
	// the project's policy: an allow the project denies stays denied. A
	// workload keeps the policy it was admitted with. A project or
	// environment the workspace does not have is NOT_FOUND. A token limited
	// to an environment sets only that environment's policy.
	SetEnvironmentNetwork(context.Context, *connect.Request[workspacev1.SetEnvironmentNetworkRequest]) (*connect.Response[workspacev1.SetEnvironmentNetworkResponse], error)
	// GetEnvironmentRetention returns an environment's retention override,
	// as stored, and the retention that applies to it: the override where it
	// shortens the workspace's, else the workspace's. An environment that
	// never set one follows its workspace. A project or environment the
	// workspace does not have is NOT_FOUND. A token limited to an
	// environment reads only that environment's.
	GetEnvironmentRetention(context.Context, *connect.Request[workspacev1.GetEnvironmentRetentionRequest]) (*connect.Response[workspacev1.GetEnvironmentRetentionResponse], error)
	// SetEnvironmentRetention replaces an environment's retention override
	// whole; an empty retention clears it. An override may only shorten the
	// workspace's: history_days above the workspace's period, or a keep
	// longer than the workspace's keep of that kind, is INVALID_ARGUMENT
	// naming the field and the limit, and so is a recording-signed-in keep
	// longer than the recording keep that applies after it. A project or
	// environment the workspace does not have is NOT_FOUND. A token limited
	// to an environment sets only that environment's.
	SetEnvironmentRetention(context.Context, *connect.Request[workspacev1.SetEnvironmentRetentionRequest]) (*connect.Response[workspacev1.SetEnvironmentRetentionResponse], error)
	// CreateEmbedToken mints an embed token for a project: a credential for
	// a web page on one of the token's origins, which spends it once to
	// fetch one of the project's ready recordings. It expires in minutes. A
	// project the workspace does not have is NOT_FOUND. A token limited to a
	// project mints only for that project, and a token limited to an
	// environment is PERMISSION_DENIED.
	CreateEmbedToken(context.Context, *connect.Request[workspacev1.CreateEmbedTokenRequest]) (*connect.Response[workspacev1.CreateEmbedTokenResponse], error)
	// ListEmbedTokens returns a project's embed tokens, oldest first, without
	// the tokens themselves.
	//
	// A page holds 100 embed tokens when page_size is zero, and 1000 at most.
	ListEmbedTokens(context.Context, *connect.Request[workspacev1.ListEmbedTokensRequest]) (*connect.Response[workspacev1.ListEmbedTokensResponse], error)
	// RevokeEmbedToken refuses an embed token before it expires. A token
	// already revoked is returned as it is.
	RevokeEmbedToken(context.Context, *connect.Request[workspacev1.RevokeEmbedTokenRequest]) (*connect.Response[workspacev1.RevokeEmbedTokenResponse], error)
}

